"""B96 100% offline concept review. No Minecraft connection or build commands."""
import json, html
from pathlib import Path
HERE=Path(__file__).resolve().parent
report=json.loads((HERE/'B96_CORE_FIRST_BUILDINGS_REPORT.json').read_text())
data=json.dumps(report,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
html_file='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>B96 | 新建築コア先行設計レビュー</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#151f32;--ink:#e5edf8;--secondary:#adc1d6;--edge:#30445a;--aqua:#55d4c6}*{box-sizing:border-box}body{font-family:system-ui,"Yu Gothic",sans-serif;color:var(--ink);background:var(--bg);margin:0}
header{background:linear-gradient(125deg,#12233d,#143a4c);padding:26px max(20px,calc((100vw - 1320px)/2));border-bottom:1px solid var(--edge)}h1{font-size:25px;margin:0 0 8px}.sub{color:#b1c7d8;font-size:14px;line-height:1.7}main{max-width:1320px;margin:auto;padding:18px}.selector{display:flex;gap:12px;flex-wrap:wrap;align-items:end;background:var(--panel);padding:16px;border:1px solid var(--edge);border-radius:12px}.selector label{display:grid;gap:5px;color:var(--secondary);font-size:12px}.selector select{min-width:175px;border:1px solid #3d546b;border-radius:8px;padding:10px;background:#0c192b;color:var(--ink);font-size:15px}.split{display:grid;grid-template-columns:minmax(480px,1.25fr) minmax(340px,.85fr);gap:14px;margin-top:14px}.panel{background:var(--panel);border:1px solid var(--edge);border-radius:12px;padding:16px;overflow:auto}.panel h2{margin:0 0 12px;font-size:17px}.canvaswrap{width:100%;overflow:auto;padding-bottom:12px}canvas{display:block;max-width:100%;height:auto;border:1px solid #3b526e;background:#091626;border-radius:6px}p,li{line-height:1.65;color:#cad9e8}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.metric{padding:12px;border:1px solid #344a64;border-radius:8px;background:#0d1a2d}.metric strong{font-size:20px;display:block;margin-top:4px}.metric span{font-size:12px;color:#adc1d6}.ok{color:#7ed7b9}.hold{color:#f6c477}.bad{color:#f2a7a3}.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:12px;color:#b5c6d8;margin:14px 0}.legend i{display:inline-block;width:10px;height:10px;margin-right:6px;border-radius:2px}.table{border-collapse:collapse;width:100%;font-size:13px}.table th,.table td{border-bottom:1px solid #34485d;padding:8px;text-align:left}.warning{border-left:3px solid #dca65d;padding:9px 14px;background:#302a22;color:#ffe5b0;border-radius:3px;margin-top:10px}footer{padding:18px 0;color:#829bb0;font-size:12px}@media(max-width:950px){.split{grid-template-columns:1fr}.selector select{min-width:140px}main{padding:12px}}
</style></head><body><header><h1>B96 · CORE-FIRST BUILDING DESIGN</h1><div class="sub">縦動線を先に配置し、部屋・共用通路を後から編成する「新建物」検討枝。既存のMinecraftワールドと296室の候補は変更しません。<br><b>NOT_PREPARED / 9 BLOCKED / 施工承認 0 / BuildPlan 0</b></div></header>
<main><section class="selector"><label>建物<select id="building"></select></label><label>新設計案<select id="branch"></select></label><label>フロア<select id="floor"></select></label><span style="color:#9eb6c6;font-size:12px">新設計内の仮想座標。既存世界のブロック変更を意味しません。</span></section>
<div class="split"><div class="panel"><h2 id="viewTitle">新間取り</h2><div class="canvaswrap"><canvas id="plan" width="870" height="620"></canvas></div><div class="legend"><span><i style="background:#44c6c0"></i>新3×3以上コア</span><span><i style="background:#738be8"></i>幅2セルの新接続路</span><span><i style="background:#a9bdd1"></i>維持部屋</span><span><i style="background:#e6bb67"></i>再配置部屋</span><span><i style="background:#e86b78"></i>未配置部屋</span><span><i style="background:#7ca362"></i>元の階段参照</span></div><div class="warning">通路幅2は新コアから既存階段「予約領域」への概念経路に限ります。実際の階段の形状、ドア開閉、避難性能、床開口、屋根、耐荷重は未検証です。</div></div>
<div class="panel"><h2>設計の品質ゲート</h2><div class="stats" id="stats"></div><p id="note"></p><h2>階別の居室配置</h2><div id="roomTable" style="max-height:340px;overflow:auto"></div><h2 style="margin-top:18px">参照B95との重複</h2><div id="collision"></div></div></div>
<footer>B96 · Offline only · fixed production source untouched · all alternatives unapproved</footer></main>
<script id="data" type="application/json">__JSON__</script><script>
const R=JSON.parse(document.getElementById('data').textContent);const get=id=>document.getElementById(id),sel=(id,list,fun)=>{let el=get(id);el.innerHTML='';list.forEach((v,i)=>{let o=document.createElement('option');o.value=i;o.textContent=fun(v);el.appendChild(o)})};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(f){let can=get('plan'),c=can.getContext('2d'),H=f.virtualFloorMaskRows.length,W=f.virtualFloorMaskRows[0].length,unit=Math.floor(Math.min(830/W,550/H)),ox=22,oy=22;
 can.width=ox*2+W*unit;can.height=oy*2+H*unit;c.fillStyle='#0e1b2d';c.fillRect(0,0,can.width,can.height);
 const cell=(x,z,color)=>{c.fillStyle=color;c.fillRect(ox+x*unit+.5,oy+z*unit+.5,unit-1,unit-1)};
 for(let z=0;z<H;z++)for(let x=0;x<W;x++)if(f.virtualFloorMaskRows[z][x]==='1')cell(x,z,'#24364a');
 for(const p of f.legacyNamedCorridorSites)cell(p.x,p.z,'#34465e');
 for(const r of f.rooms){if(!r.room)continue;const color=r.relocation==='UNCHANGED_IN_NEW_BRANCH'?'#a8bbca':'#e6bc6c';for(let z=r.room.z;z<r.room.z+r.room.depth;z++)for(let x=r.room.x;x<r.room.x+r.room.width;x++)cell(x,z,color)}
 for(const p of f.legacyReferenceCores.stairs)cell(p.x,p.z,'#76a55e');for(const p of f.legacyReferenceCores.elevators)cell(p.x,p.z,'#9d77ce');
 for(const p of f.route.sites)cell(p.x,p.z,'#637ce7');for(let z=f.core.z;z<f.core.z+f.core.depth;z++)for(let x=f.core.x;x<f.core.x+f.core.width;x++)cell(x,z,'#3dd2c5');
 c.textBaseline='middle';c.textAlign='center';for(const r of f.rooms){if(!r.room)continue;c.fillStyle='#152236';c.font=`bold ${Math.max(9,Math.min(12,unit*.42))}px sans-serif`;c.fillText(r.id.split('-').at(-1),ox+(r.room.x+r.room.width/2)*unit,oy+(r.room.z+r.room.depth/2)*unit)}
 c.strokeStyle='#f0fafb';c.lineWidth=2;c.strokeRect(ox+f.core.x*unit,oy+f.core.z*unit,f.core.width*unit,f.core.depth*unit);
}
function details(){let b=R.buildings[+get('building').value],o=b.options[+get('branch').value],f=o.floors[+get('floor').value],s=o.summary;
 get('viewTitle').textContent=`${b.buildingId} / L${f.level} · 新コア ${o.core.width}×${o.core.depth} @(${o.core.x}, ${o.core.z})`;draw(f);
 let items=[['設計全体の配置室数',`${s.allocatedRooms} / ${s.nominalRooms}`],['面積保持率',`${(100*s.retentionRatio).toFixed(1)}%`],['新通路に接する部屋',`${s.roomDoorwayAdjacencyChecksPassed} / ${s.roomDoorwayAdjacencyChecksTotal}`],['幅2の経路が全階接続',s.fullConceptCorridorConnections?'概念的にYES':'NO'],['旧候補の保護位置と重複',String(o.baselineOverlay.baselinePreviouslyProtectedSiteContacts)],['未承認の階間開口サイト',String(o.tiers.virtualSlabOpeningsBetweenLevels)],['当階の未配置室',String(f.stats.unallocatedRooms)],['当階の面積',`${f.stats.virtualAllocatedArea} / ${f.stats.nominalRoomArea}`]];
 get('stats').innerHTML=items.map(([k,v])=>`<div class="metric"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('');
 get('note').innerHTML=`<span class="hold">設計の暫定評価:</span> ${s.roomDoorwayAdjacencyChecksPassed<s.nominalRooms?'すべての居室への新通路接続は未達。':'入口枠・動線の実体験証は未実施。'} ${s.unallocatedRooms?'未配置室を残す案であり、部屋数減少の承認は必要。':'元の部屋数を仮想的に維持。'} 旧名目廊下に隣接する室は ${s.adjacentToUnverifiedLegacyCorridor} 室ですが、それ自体は施工・開閉保証ではありません。`;
 get('roomTable').innerHTML='<table class="table"><thead><tr><th>室</th><th>原面積</th><th>新面積</th><th>新通路</th><th>状態</th></tr></thead><tbody>'+f.rooms.map(r=>{let door=f.entrances.find(d=>d.roomId===r.id);return `<tr><td>${esc(r.id)}</td><td>${r.originalArea}</td><td>${r.room?r.room.width*r.room.depth:'—'}</td><td>${door?.hasAdjacentTwoWideCorridor?'接する':'未接続'}</td><td class="${!r.room?'bad':r.relocation==='MOVED_OR_RETILED'?'hold':''}">${!r.room?'未配置':r.relocation==='MOVED_OR_RETILED'?'再配置':'維持'}</td></tr>`}).join('')+'</tbody></table>';
 get('collision').innerHTML=`<p>元の未承認296候補の占有予約領域と重なるセルは <b>${o.baselineOverlay.baselinePreviouslyProtectedSiteContacts}</b>。この値が0でも、既存の本番建築を置換してよいことにはなりません。設計比較は<strong>新しい別棟の概念案</strong>です。</p><p class="bad">建築承認 0 / ワールド操作 0 / 元の建物の変更 0</p>`;
}
function init(){sel('building',R.buildings,b=>b.buildingId);get('building').addEventListener('change',()=>{rebuild();});get('branch').addEventListener('change',()=>{floors();});get('floor').addEventListener('change',details);rebuild();}
function rebuild(){let b=R.buildings[+get('building').value];sel('branch',b.options,o=>`${o.id}: ${o.core.width}×${o.core.depth} / ${o.siteSelection.focusPattern?'重点'+o.siteSelection.focusPattern:'一般'}`);floors();}
function floors(){let b=R.buildings[+get('building').value],o=b.options[+get('branch').value];sel('floor',o.floors,f=>`L${f.level}：${f.stats.allocatedRooms}/${f.stats.originalRooms}室`);details();}
init();</script></body></html>'''
out=HERE/'B96_CORE_FIRST_REVIEW.html';out.write_text(html_file.replace('__JSON__',data),encoding='utf8');print(out,len(data))
